    // Objective: Minimize post_residual, but prioritize fits that leave space for next_item_size.
    // We heavily penalize creating small "dead space" fragments (e.g., 1-9) that are unlikely to fit future items.

    let mut score = post_residual as f64;

    // 1. If this is a new bin, apply a threshold penalty to discourage opening new bins unless necessary.
    if bin_residual == bin_capacity {
        // Penalty is scaled by the scarcity of current options. 
        // If many bins fit, opening a new one is highly penalized.
        score += 25.0 + (fitting_bins_count as f64 * 5.0);
    } else {
        // 2. Lookahead: If current post_residual is slightly smaller than next_item_size,
        // it creates a "dead zone". Penalize this.
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }

        // 3. Fragmentation avoidance: Penalize remainders that are too small to be useful (under 10).
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }

        // 4. Density Balancing: If this bin's residual is significantly below the current mean, 
        // we prefer filling it to keep bins tightly packed.
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // 5. Progression awareness: As we approach the end of the stream, be more aggressive
    // about using existing bins to avoid leftover bin count.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= 10.0 * (1.0 - (fitting_bins_count as f64 / (open_bins_count as f64 + 1.0)));
    }

    score
