    // but large enough to waste capacity. 
    // We penalize small residuals more heavily if the stream is nearing completion.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * (1.0 + progress * 2.0);
    }

    // Lookahead interaction: If the next item doesn't fit in the remaining space,
    // we penalize this bin to encourage saving space for the next item.
    if next_item_size > 0 && next_item_size > post_residual {
        score += (next_item_size as f64 - post) * 0.5;
    }

    // Threshold for opening a new bin:
    // If this is a new bin (residual == capacity), we calculate a "cost" to open it.
    // As the stream progresses, we become more conservative about opening new bins.
    if bin_residual == bin_capacity {
        // The cost to start a new bin is non-linear: it scales with the average
        // residual of existing bins. If existing bins are very empty, we prefer
        // using them rather than opening a new one.
        score = mean_residual * 0.8 + (1.0 - progress) * 25.0;
    } else {
        // If this is an existing bin, we penalize bins that deviate from the mean.
        // This encourages "leveling" the residuals across bins.
        score += (post - mean_residual).abs() * 0.2;
    }

    // If this is the last chance to fit the item in an existing bin, 
    // prioritize it heavily to avoid the new bin cost.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    // Penalize creating small, unusable gaps (1..10 range is critical).
    let mut score = post;

    // If the residual is too small for any future item (assuming min size ~10), 
    // it's "dead space". Penalize heavily if the bin isn't nearly full.
    if post > 0.0 && post < 10.0 {
        score += 50.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: if the next item fits into the current post-placement residual, 
    // prioritize this bin to maximize packing density.
    if next_item_size > 0 && post >= next_item_size as f64 {
        score -= 25.0 * (1.0 - (post - next_item_size as f64) / 100.0);
    }

    // Dynamic pressure: As the stream progresses, become more conservative about opening new bins.
    // If this is a new bin (post == bin_capacity - item_size), penalize it more as we approach the end.
    if bin_residual == bin_capacity {
        score += 30.0 * progress;

        // If we have other bins that can fit the item, discourage opening a new one.
        if fitting_bins_count > 1 {
            score += 40.0;
        }
    }

    // Coupling with mean_residual: If this bin is significantly emptier than the average, 
    // it is a good candidate to fill to bring the mean_residual down.
    if (bin_residual as f64) > mean_residual {
        score -= 10.0 * ((bin_residual as f64 - mean_residual) / 100.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize "wastage" while balancing the probability of fitting the next item.
    // We prioritize bins that leave a post_residual that is either 0 (perfect fit) or 
    // highly compatible with the next_item_size (harmonic alignment).

    let mut score = post_residual as f64;

    // 1. Harmonic alignment: If post_residual is small, it creates "unusable" space (dead space).
    // Penalize small residuals that are too small to fit common items (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead optimization: If the next item can fit in the current post_residual,
    // strongly incentivize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Prevent premature new bin opening:
    // If we are considering a new bin (bin_residual == bin_capacity), 
    // only choose it if the current fitting_bins_count is low or if current bins are full.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one can fit the item.
            score += 150.0 - (open_bins_count as f64 * 2.0);
        } else {
            // If no existing bin fits, normalize the cost of a new bin.
            score = 50.0;
        }
    }

    // 4. Global state awareness:
    // As the stream progresses, prioritize closing bins (lower mean_residual).
    let progress = step_index as f64 / total_items as f64;
    score += (mean_residual * progress);

    // 5. Modulo-based "harmonic" preference:
    // Favor residuals that are multiples of 20 to keep bins "open" for standard item sizes.
    let remainder = post_residual % 20;
    score += (remainder as f64) * 0.2;

    score
}
